for (const [name, table] of [["hand-picked", HAND], ["random", RANDOM]] as const) {
  test(`ppr matches TLC (${name}, ${table.length} cases)`, () => {
    for (const [input, expected, width] of table) {
      const actual = width === undefined ? ppr(input) : ppr(input, width);
      assert.equal(actual, expected, `ppr(${JSON.stringify(input)}, ${width ?? 80})`);
    }
  });
}

test("ppr table is large enough and exercises wrapping", () => {
  const all = [...HAND, ...RANDOM];
  assert.ok(all.length >= 150);
  assert.ok(all.filter(([i, e]) => i !== e).length >= 80);
});

test("ppr default width is 80", () => {
  const v = "{" + Array.from({ length: 40 }, (_, i) => i).join(", ") + "}";
  assert.equal(ppr(v), ppr(v, 80));
  assert.equal(ppr(v, 1000), v);
});
